CREATE TABLE IF NOT EXISTS accounting_dimension_definition_events (id INTEGER PRIMARY KEY,dimension_id TEXT NOT NULL,kind TEXT NOT NULL,name TEXT NOT NULL,event_type TEXT NOT NULL CHECK(event_type='defined'),actor TEXT NOT NULL,principal TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(dimension_id,event_type));
CREATE TABLE IF NOT EXISTS accounting_dimension_member_events (id INTEGER PRIMARY KEY,dimension_id TEXT NOT NULL,member_id TEXT NOT NULL,name TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('active','inactive')),effective_from TEXT,effective_to TEXT,event_type TEXT NOT NULL CHECK(event_type='defined'),actor TEXT NOT NULL,principal TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(dimension_id,member_id,event_type));
CREATE TABLE IF NOT EXISTS accounting_dimension_assignment_events (id INTEGER PRIMARY KEY,journal_line_id INTEGER NOT NULL REFERENCES journal_lines(id),journal_entry_id INTEGER NOT NULL REFERENCES journal_entries(id),journal_entry_hash TEXT NOT NULL CHECK(length(journal_entry_hash)=64),line_currency TEXT NOT NULL CHECK(length(line_currency)=3),line_amount_minor INTEGER NOT NULL CHECK(line_amount_minor>=0),allocations_json TEXT NOT NULL CHECK(json_valid(allocations_json)),source TEXT NOT NULL CHECK(source IN ('reviewed','imported')),plan_hash TEXT NOT NULL CHECK(length(plan_hash)=64),event_type TEXT NOT NULL CHECK(event_type IN ('assigned','superseded')),supersedes_assignment_id INTEGER REFERENCES accounting_dimension_assignment_events(id),idempotency_key TEXT UNIQUE,reason TEXT,actor TEXT NOT NULL,principal TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(journal_line_id,event_type,plan_hash));
CREATE VIEW IF NOT EXISTS current_accounting_dimension_definitions AS SELECT * FROM accounting_dimension_definition_events;
CREATE VIEW IF NOT EXISTS current_accounting_dimension_members AS SELECT * FROM accounting_dimension_member_events;
CREATE VIEW IF NOT EXISTS current_accounting_dimension_assignments AS SELECT a.* FROM accounting_dimension_assignment_events a WHERE a.event_type='assigned' AND NOT EXISTS(SELECT 1 FROM accounting_dimension_assignment_events s WHERE s.event_type='superseded' AND s.supersedes_assignment_id=a.id);
CREATE TRIGGER IF NOT EXISTS accounting_dimension_definition_events_no_update BEFORE UPDATE ON accounting_dimension_definition_events BEGIN SELECT RAISE(ABORT,'accounting dimension definition events are append-only'); END;
CREATE TRIGGER IF NOT EXISTS accounting_dimension_definition_events_no_delete BEFORE DELETE ON accounting_dimension_definition_events BEGIN SELECT RAISE(ABORT,'accounting dimension definition events are append-only'); END;
CREATE TRIGGER IF NOT EXISTS accounting_dimension_member_events_no_update BEFORE UPDATE ON accounting_dimension_member_events BEGIN SELECT RAISE(ABORT,'accounting dimension member events are append-only'); END;
CREATE TRIGGER IF NOT EXISTS accounting_dimension_member_events_no_delete BEFORE DELETE ON accounting_dimension_member_events BEGIN SELECT RAISE(ABORT,'accounting dimension member events are append-only'); END;
CREATE TRIGGER IF NOT EXISTS accounting_dimension_assignment_events_no_update BEFORE UPDATE ON accounting_dimension_assignment_events BEGIN SELECT RAISE(ABORT,'accounting dimension assignment events are append-only'); END;
CREATE TRIGGER IF NOT EXISTS accounting_dimension_assignment_events_no_delete BEFORE DELETE ON accounting_dimension_assignment_events BEGIN SELECT RAISE(ABORT,'accounting dimension assignment events are append-only'); END;
